package com.marketintel.service;
import com.marketintel.model.*;import org.springframework.stereotype.Service;import java.time.*;import java.util.*;
@Service public class WalkForwardMlService {private final FeatureStoreService store;public WalkForwardMlService(FeatureStoreService store){this.store=store;}
 public WalkForwardResult validate(String symbol,WalkForwardRequest r){var f=store.load(symbol,Instant.EPOCH,Instant.now());if(f.size()<r.trainingSize()+r.testSize())throw new IllegalArgumentException("Not enough stored features for walk-forward validation.");List<WalkForwardFold> folds=new ArrayList<>();int start=0,totalTrain=0,totalTest=0,tp=0,tn=0,fp=0,fn=0,fold=1;while(start+r.trainingSize()+r.testSize()<=f.size()&&fold<=r.folds()){var train=f.subList(start,start+r.trainingSize());var test=f.subList(start+r.trainingSize(),start+r.trainingSize()+r.testSize());double[][]x=new double[train.size()-1][];int[]y=new int[train.size()-1];for(int i=0;i<x.length;i++){x[i]=features(train.get(i));y[i]=train.get(i+1).close()>train.get(i).close()?1:0;}var model=new LogisticRegressionModel(8,r.learningRate());model.fit(x,y,r.epochs());int fTp=0,fTn=0,fFp=0,fFn=0;for(int i=0;i<test.size()-1;i++){int actual=test.get(i+1).close()>test.get(i).close()?1:0;int pred=model.predict(features(test.get(i)));if(pred==1&&actual==1)fTp++;else if(pred==0&&actual==0)fTn++;else if(pred==1)fFp++;else fFn++;}int n=fTp+fTn+fFp+fFn;double acc=n==0?0:(double)(fTp+fTn)/n,prec=fTp+fFp==0?0:(double)fTp/(fTp+fFp),rec=fTp+fFn==0?0:(double)fTp/(fTp+fFn),f1=prec+rec==0?0:2*prec*rec/(prec+rec);folds.add(new WalkForwardFold(fold,train.size()-1,test.size()-1,acc,prec,rec,f1));totalTrain+=train.size()-1;totalTest+=test.size()-1;tp+=fTp;tn+=fTn;fp+=fFp;fn+=fFn;start+=r.step();fold++;}int n=tp+tn+fp+fn;double acc=n==0?0:(double)(tp+tn)/n,prec=tp+fp==0?0:(double)tp/(tp+fp),rec=tp+fn==0?0:(double)tp/(tp+fn),f1=prec+rec==0?0:2*prec*rec/(prec+rec);return new WalkForwardResult(symbol,"logistic-regression",totalTrain,totalTest,acc,prec,rec,f1,folds);}
 private double[]features(FeaturePoint x){return new double[]{x.return1(),x.sma20()==0?0:x.close()/x.sma20()-1,x.sma50()==0?0:x.close()/x.sma50()-1,x.ema21()==0?0:x.close()/x.ema21()-1,(x.rsi14()-50)/50,x.atr14()==0?0:x.atr14()/x.close(),x.relativeVolume20()-1,1};}}
